<script setup lang="ts">
import { onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { listStores, listUsers, updateUser, type AdminUser, type Store } from "../api";
const route = useRoute(); const router = useRouter(); const stores = ref<Store[]>([]); const form = ref({ email: "", displayName: "", role: "technician" as AdminUser["role"], active: true, password: "", storeId: "" }); const error = ref("");
onMounted(async () => { const [users, loadedStores] = await Promise.all([listUsers(), listStores()]); stores.value = loadedStores.filter((store) => store.active); const user = users.find((item) => item.id === route.params.id); if (user) form.value = { email: user.email, displayName: user.displayName, role: user.role, active: user.active, password: "", storeId: user.storeId ?? "" }; });
async function save(): Promise<void> { try { const input = { ...form.value, password: form.value.password || undefined }; const user = await updateUser(String(route.params.id), input); void router.push({ name: "admin.users.detail.general", params: { id: user.id } }); } catch (reason) { error.value = (reason as Error).message; } }
</script>
<template><form class="entity-form" @submit.prevent="save"><header><div><p class="eyebrow">Administracion</p><h1>Editar usuario</h1></div></header><fieldset><legend>Cuenta</legend><label>Nombre<input v-model="form.displayName" required maxlength="160" /></label><label>Email<input v-model="form.email" type="email" required maxlength="320" /></label><label>Rol<select v-model="form.role"><option value="admin">Administrador</option><option value="technician">Tecnico</option><option value="customer">Cliente</option></select></label><label v-if="form.role === 'technician'">Tienda<select v-model="form.storeId" required><option value="">Selecciona una tienda</option><option v-for="store in stores" :key="store.id" :value="store.id">{{ store.name }}</option></select></label><label>Estado<select v-model="form.active"><option :value="true">Activo</option><option :value="false">Inactivo</option></select></label><label>Nueva contraseña<input v-model="form.password" type="password" minlength="12" autocomplete="new-password" placeholder="Dejar vacio para conservarla" /></label></fieldset><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="router.back()">Cancelar</button><button>Guardar cambios</button></footer></form></template>